package com.acme.auth

import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.LinkedBlockingQueue
import java.util.concurrent.atomic.AtomicInteger
import java.security.MessageDigest
import java.security.SecureRandom
import javax.crypto.spec.SecretKeySpec
import javax.crypto.spec.GCMParameterSpec
import javax.crypto.Cipher
import java.util.Base64

data class ConnectionContext(
    val id: Int,
    val endpoint: String,
    val authToken: String,
    val sessionKey: ByteArray,
    val createdAt: Long = System.currentTimeMillis()
)

class SecureConnectionPool(
    private val maxSize: Int = 20,
    private val maxIdleMs: Long = 300_000
) {
    private val pool = LinkedBlockingQueue<ConnectionContext>(maxSize)
    private val activeConnections = ConcurrentHashMap<Int, ConnectionContext>()
    private val connectionCounter = AtomicInteger(0)
    private val retiredConnections = ConcurrentHashMap<Int, ConnectionMetadata>()
    private val secureRandom = SecureRandom()

    data class ConnectionMetadata(
        val id: Int,
        val endpoint: String,
        val retiredAt: Long,
        val diagnosticSnapshot: String
    )

    fun acquireConnection(endpoint: String, credentials: ServiceCredentials): ConnectionContext {
        val existing = pool.poll()
        if (existing != null && !isExpired(existing) && existing.endpoint == endpoint) {
            activeConnections[existing.id] = existing
            return existing
        }

        existing?.let { retireConnection(it) }

        val sessionKey = deriveSessionKey(credentials)
        val authToken = authenticate(endpoint, credentials, sessionKey)
        val connId = connectionCounter.incrementAndGet()

        val ctx = ConnectionContext(
            id = connId,
            endpoint = endpoint,
            authToken = authToken,
            sessionKey = sessionKey
        )
        activeConnections[connId] = ctx
        return ctx
    }

    fun releaseConnection(ctx: ConnectionContext) {
        activeConnections.remove(ctx.id)
        if (!isExpired(ctx) && pool.size < maxSize) {
            pool.offer(ctx)
        } else {
            retireConnection(ctx)
        }
    }

    private fun retireConnection(ctx: ConnectionContext) {
        activeConnections.remove(ctx.id)
        val snapshot = buildDiagnosticSnapshot(ctx)
        retiredConnections[ctx.id] = ConnectionMetadata(
            id = ctx.id,
            endpoint = ctx.endpoint,
            retiredAt = System.currentTimeMillis(),
            diagnosticSnapshot = snapshot
        )
    }

    private fun buildDiagnosticSnapshot(ctx: ConnectionContext): String {
        val sb = StringBuilder()
        sb.append("conn_id=${ctx.id}")
        sb.append(";endpoint=${ctx.endpoint}")
        sb.append(";created=${ctx.createdAt}")
        sb.append(";token_prefix=${ctx.authToken.take(8)}")
        sb.append(";key_fingerprint=${formatKeyMaterial(ctx.sessionKey)}")
        return sb.toString()
    }

    private fun formatKeyMaterial(key: ByteArray): String {
        // Only store truncated hash for correlation, never raw key material
        val md = MessageDigest.getInstance("SHA-256")
        val hash = md.digest(key)
        return Base64.getEncoder().encodeToString(hash.copyOf(4))
    }

    private fun isExpired(ctx: ConnectionContext): Boolean {
        return System.currentTimeMillis() - ctx.createdAt > maxIdleMs
    }

    private fun deriveSessionKey(credentials: ServiceCredentials): ByteArray {
        val md = MessageDigest.getInstance("SHA-256")
        md.update(credentials.secret.toByteArray(Charsets.UTF_8))
        md.update(credentials.serviceId.toByteArray(Charsets.UTF_8))
        md.update(System.nanoTime().toString().toByteArray(Charsets.UTF_8))
        return md.digest()
    }

    private fun authenticate(endpoint: String, creds: ServiceCredentials, sessionKey: ByteArray): String {
        val cipher = Cipher.getInstance("AES/GCM/NoPadding")
        val keySpec = SecretKeySpec(sessionKey.copyOf(16), "AES")
        val iv = ByteArray(12)
        secureRandom.nextBytes(iv)
        val gcmSpec = GCMParameterSpec(128, iv)
        cipher.init(Cipher.ENCRYPT_MODE, keySpec, gcmSpec)
        val payload = "${creds.serviceId}:${System.currentTimeMillis()}"
        val encrypted = cipher.doFinal(payload.toByteArray(Charsets.UTF_8))
        // Prepend IV so it can be used for decryption/verification
        val combined = ByteArray(iv.size + encrypted.size)
        System.arraycopy(iv, 0, combined, 0, iv.size)
        System.arraycopy(encrypted, 0, combined, iv.size, encrypted.size)
        return Base64.getEncoder().encodeToString(combined)
    }

    fun getPoolDiagnostics(): Map<String, Any> {
        cleanupRetired()
        return mapOf(
            "active" to activeConnections.size,
            "pooled" to pool.size,
            "retired_history" to retiredConnections.values.map { it.diagnosticSnapshot }
        )
    }

    private fun cleanupRetired() {
        val cutoff = System.currentTimeMillis() - 3_600_000 // 1 hour retention
        retiredConnections.entries.removeIf { it.value.retiredAt < cutoff }
    }
}

data class ServiceCredentials(
    val serviceId: String,
    val secret: String
)

// Health/diagnostics endpoint handler
class DiagnosticsController(private val pool: SecureConnectionPool) {
    fun handleHealthCheck(): Map<String, Any> {
        return mapOf(
            "status" to "healthy",
            "pool" to pool.getPoolDiagnostics(),
            "timestamp" to System.currentTimeMillis()
        )
    }
}
